    /// <summary>Proves an editor can close an open ticket from its detail page and the status changes to closed.</summary>
    [Test]
    [Description("Editor closes an open ticket")]
    [Property("SeedProfile", "default")]
    [Category("happy-path")]
    public async Task EditorClosesTicket()
    {
        await Page.GotoAsync("/tickets/1");
        // 1. Ticket #1 starts open
        await Expect(Page.GetByTestId("ticket-status")).ToHaveTextAsync("open");
        // 2. Click Close ticket
        await Page.GetByRole(AriaRole.Button, new() { Name = "Close ticket" }).ClickAsync();
        // 3. The status shows closed
        await Expect(Page.GetByTestId("ticket-status")).ToHaveTextAsync("closed");
    }

    /// <summary>Proves an editor can reopen a closed ticket and the status changes back to open.</summary>
    [Test]
    [Description("Editor reopens a closed ticket")]
    [Property("SeedProfile", "default")]
    [Category("happy-path")]
    public async Task EditorReopensTicket()
    {
        await Page.GotoAsync("/tickets/3");
        // 1. Ticket #3 starts closed
        await Expect(Page.GetByTestId("ticket-status")).ToHaveTextAsync("closed");
        // 2. Click Reopen ticket
        await Page.GetByRole(AriaRole.Button, new() { Name = "Reopen ticket" }).ClickAsync();
        // 3. The status shows open
        await Expect(Page.GetByTestId("ticket-status")).ToHaveTextAsync("open");
    }

    /// <summary>Proves the ticket list's status filter reflects a ticket that was just closed.</summary>
    [Test]
    [Description("A closed ticket moves from the open filter to the closed filter")]
    [Property("SeedProfile", "default")]
    [Category("edge")]
    public async Task ClosedTicketInClosedFilter()
    {
        await Page.GotoAsync("/tickets/2");
        // 1. Close ticket #2
        await Page.GetByTestId("ticket-toggle-status").ClickAsync();
        // 2. Wait for the status to show closed
        await Expect(Page.GetByTestId("ticket-status")).ToHaveTextAsync("closed");
        // 3. Open the ticket list
        await Page.GotoAsync("/tickets");
        // 4. Filter to closed tickets
        await Page.GetByTestId("status-filter").SelectOptionAsync("closed");
        // 5. Ticket #2 is listed
        await Expect(Page.GetByTestId("ticket-row-2")).ToBeVisibleAsync();
        // 6. Filter to open tickets
        await Page.GetByTestId("status-filter").SelectOptionAsync("open");
        // 7. Ticket #2 is not listed
        await Expect(Page.GetByTestId("ticket-row-2")).ToHaveCountAsync(0);
    }
}

